text:
This page lets you look up a Last.fm user and see the most recent music they listened to.

viewof searchControl = {
  const form = html`
    &lt;form style="max-width: 440px; margin-bottom: 1.25rem;"&gt;
      &lt;label style="display: block; font-weight: 600; font-size: 0.95rem; margin-bottom: 6px;"&gt;Last.fm Username:&lt;/label&gt;
      &lt;div style="display: flex; gap: 8px; align-items: center;"&gt;
        &lt;input type="text" placeholder="e.g. rj" class="form-control" style="flex: 1; height: 38px; border-radius: 6px;" /&gt;
        &lt;button type="submit" class="btn btn-primary" style="height: 38px; padding: 0 16px; border-radius: 6px; font-weight: 500;"&gt;Search&lt;/button&gt;
        &lt;button type="button" class="btn btn-outline-secondary" title="Refresh" style="height: 38px; width: 38px; min-width: 38px; padding: 0; display: inline-flex; align-items: center; justify-content: center; border-radius: 6px;"&gt;
          &lt;svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" fill="currentColor" viewBox="0 0 16 16"&gt;
            &lt;path fill-rule="evenodd" d="M8 3a5 5 0 1 0 4.546 2.914.5.5 0 0 1 .908-.417A6 6 0 1 1 8 2z"/&gt;
            &lt;path d="M8 4.466V.534a.25.25 0 0 1 .41-.192l2.36 1.966c.12.1.12.284 0 .384L8.41 4.658A.25.25 0 0 1 8 4.466"/&gt;
          &lt;/svg&gt;
        &lt;/button&gt;
      &lt;/div&gt;
    &lt;/form&gt;
  `;

  const input = form.querySelector('input');
  const refreshBtn = form.querySelector('button[type="button"]');

  form.value = { username: "", trigger: 0 };

  form.onsubmit = (e) =&gt; {
    e.preventDefault();
    form.value = { username: input.value.trim(), trigger: form.value.trigger + 1 };
    form.dispatchEvent(new CustomEvent("input"));
  };

  refreshBtn.onclick = () =&gt; {
    form.value = { username: input.value.trim(), trigger: form.value.trigger + 1 };
    form.dispatchEvent(new CustomEvent("input"));
  };

  return form;
}

username = searchControl.username;
















function timeAgo(uts) {
  if (!uts) return "unknown time ago";
  const seconds = Math.floor((Date.now() / 1000) - Number(uts));
  if (seconds &lt; 60) return `${Math.max(1, seconds)} seconds ago`;
  const minutes = Math.floor(seconds / 60);
  if (minutes &lt; 60) return `${minutes} minute${minutes === 1 ? '' : 's'} ago`;
  const hours = Math.floor(minutes / 60);
  if (hours &lt; 24) return `${hours} hour${hours === 1 ? '' : 's'} ago`;
  const days = Math.floor(hours / 24);
  return `${days} day${days === 1 ? '' : 's'} ago`;
}

recentData = {
  searchControl.trigger;
  if (!username) return null;
  const apiKey = "b914193d6c62aabcd83adf2b6c457a5f";
  const url = `https://ws.audioscrobbler.com/2.0/?method=user.getrecenttracks&user=${encodeURIComponent(username)}&api_key=${apiKey}&format=json&limit=1&_t=${Date.now()}`;
  const response = await fetch(url);
  return await response.json();
}

track = {
  if (!recentData || !recentData.recenttracks || !recentData.recenttracks.track) return null;
  const t = recentData.recenttracks.track;
  return Array.isArray(t) ? t[0] : t;
}

trackInfo = {
  if (!username || !track) return null;
  const apiKey = "b914193d6c62aabcd83adf2b6c457a5f";
  const songName = track.name || "";
  const artistName = track.artist ? (track.artist["#text"] || track.artist.name) : "";
  if (!songName || !artistName) return null;
  try {
    const url = `https://ws.audioscrobbler.com/2.0/?method=track.getInfo&artist=${encodeURIComponent(artistName)}&track=${encodeURIComponent(songName)}&username=${encodeURIComponent(username)}&api_key=${apiKey}&format=json&_t=${Date.now()}`;
    const response = await fetch(url);
    return await response.json();
  } catch (e) {
    return null;
  }
}

html`${
  !username ? html`&lt;em&gt;Enter a Last.fm username above to see their most recent track.&lt;/em&gt;` :
  recentData?.error ? html`&lt;div class="alert alert-danger" style="margin-top: 10px;"&gt;❌ ${recentData.message}&lt;/div&gt;` :
  !track ? html`&lt;div class="alert alert-warning" style="margin-top: 10px;"&gt;No listening history found for this user.&lt;/div&gt;` :
  (() =&gt; {
    const isNowPlaying = track["@attr"] && track["@attr"].nowplaying === "true";
    const songName = track.name || "Unknown Song";
    const artistName = track.artist ? (track.artist["#text"] || track.artist.name) : "Unknown Artist";
    const albumName = track.album ? track.album["#text"] : "Unknown Album";
    const timingText = isNowPlaying 
      ? `${username} is listening to this right now!` 
      : `listened ${timeAgo(track.date?.uts)}`;
    const isLoved = trackInfo?.track?.userloved === "1";

    const images = track.image;
    let imageUrl = "";
    if (Array.isArray(images)) {
      const preferred = images.find(img =&gt; img.size === "extralarge") || 
                        images.find(img =&gt; img.size === "large") || 
                        images[images.length - 1];
      imageUrl = preferred ? preferred["#text"] : "";
    } else if (images && images["#text"]) {
      imageUrl = images["#text"];
    }

    return html`
      &lt;div class="card p-3 my-3" style="max-width: 360px; border: 1px solid #ddd; border-radius: 8px; padding: 16px; margin-top: 15px;"&gt;
        &lt;h4 style="margin-top: 0; margin-bottom: 12px; font-weight: 600; font-size: 1.15rem; color: #333;"&gt;Most Recent Scrobble&lt;/h4&gt;
        ${imageUrl ? html`&lt;img src="${imageUrl}" alt="${albumName}" style="width: 100%; border-radius: 6px; margin-bottom: 12px; display: block;" /&gt;` : ""}
        &lt;div style="font-size: 1.5rem; font-weight: bold; line-height: 1.2; margin-bottom: 4px;"&gt;${songName}&lt;/div&gt;
        &lt;div style="font-size: 1.1rem; color: #444; margin-bottom: 2px;"&gt;by ${artistName}&lt;/div&gt;
        &lt;div style="font-size: 1rem; color: #666; margin-bottom: 6px;"&gt;on ${albumName || "Unknown Album"}&lt;/div&gt;
        &lt;div style="font-size: 0.8rem; color: #888;"&gt;${timingText}&lt;/div&gt;
        ${isLoved ? html`&lt;div style="font-size: 0.85rem; color: #e63946; margin-top: 6px; font-weight: 500;"&gt;❤️ ${username} loves this track!&lt;/div&gt;` : ""}
      &lt;/div&gt;
    `;
  })()
}`
